import raw from "./data.json";
import type { Ev } from "./components/Trace";

// Generated by `python -m examples.video_data video/src/data.json` from real runs.
type Finding = { category: string; signature: string; first_run: number; hits: number; minimal: string[];
  trace: number; reduced: number | null };
type RegressRow = { label: string; faults: string[]; verdict: string; compatibility: string;
  divergence_seq: number | null; matched: number; total: number };

export type Data = {
  portal: { events: Ev[]; violation: string; applications: number; replay_identical: boolean };
  reduction: { events: Ev[]; before: number; after: number; tests: number; anchor: number };
  explore: { runs: number; space: Record<string, number>; explored: Record<string, number>; sites: string[];
    schedules: string[]; outcomes: string[]; findings: Finding[]; crash_trace: Ev[] };
  regress: { rows: RegressRow[]; compare: { old: Ev[]; new: Ev[]; position: number; kind: string } };
  citalab: { agreement: number; episodes: number; failures: number; identical_requests: number; answers: string[];
    m5: Ev[]; h: Ev[]; divergence: { position: number; kind: string; values: [string, unknown, unknown][] };
    reduction: Ev[]; reduced_before: number; reduced_after: number; reexecuted: number | null };
  metrics: { found: number; defective: number; false_alarms: number; correct: number; record_us: number;
    share_percent: number; disk_bytes: number; deterministic: boolean };
};

export const D = raw as unknown as Data;
